/** Upstream's `useIsMobile(mobileBreakpoint = 768)` default. */
export const DEFAULT_MOBILE_BREAKPOINT = 768;

/**
 * A runes reader over `(max-width: <breakpoint - 1>px)`, SSR-safe.
 *
 * `current` is seeded `false` — matching upstream's `!!undefined` before its effect runs — and
 * corrects inside an `$effect` on the client. Exactly one `change` listener is registered per
 * instance; changing the breakpoint getter tears the old query down and creates a new one.
 */
export class IsMobile {
	/** `true` when the viewport is narrower than the breakpoint. */
	current: boolean = $state(false);

	constructor(getBreakpoint: () => number = () => DEFAULT_MOBILE_BREAKPOINT) {
		$effect(() => {
			const breakpoint = getBreakpoint();

			if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return;

			// The query string is copied verbatim from upstream's `use-mobile.ts`.
			const query = window.matchMedia(`(max-width: ${breakpoint - 1}px)`);
			const onChange = () => {
				this.current = query.matches;
			};

			this.current = query.matches;
			query.addEventListener('change', onChange);

			return () => query.removeEventListener('change', onChange);
		});
	}
}

/** Reusable by any component. Must be called during component initialisation. */
export function useIsMobile(getBreakpoint?: () => number): IsMobile {
	return new IsMobile(getBreakpoint);
}

import Root from './responsive-dialog.svelte';
import Trigger from './responsive-dialog-trigger.svelte';
import Close from './responsive-dialog-close.svelte';
import Portal from './responsive-dialog-portal.svelte';
import Overlay from './responsive-dialog-overlay.svelte';
import Content from './responsive-dialog-content.svelte';
import Header from './responsive-dialog-header.svelte';
import Footer from './responsive-dialog-footer.svelte';
import Title from './responsive-dialog-title.svelte';
import Description from './responsive-dialog-description.svelte';

export type { ResponsiveDialogRootProps } from './responsive-dialog.svelte';
export type { ResponsiveDialogTriggerProps } from './responsive-dialog-trigger.svelte';
export type { ResponsiveDialogCloseProps } from './responsive-dialog-close.svelte';
export type { ResponsiveDialogPortalProps } from './responsive-dialog-portal.svelte';
export type { ResponsiveDialogOverlayProps } from './responsive-dialog-overlay.svelte';
export type { ResponsiveDialogContentProps } from './responsive-dialog-content.svelte';
export type { ResponsiveDialogHeaderProps } from './responsive-dialog-header.svelte';
export type { ResponsiveDialogFooterProps } from './responsive-dialog-footer.svelte';
export type { ResponsiveDialogTitleProps } from './responsive-dialog-title.svelte';
export type { ResponsiveDialogDescriptionProps } from './responsive-dialog-description.svelte';

export {
	ResponsiveDialogState,
	getResponsiveDialogContext,
	hasResponsiveDialogContext,
	setResponsiveDialogContext,
	type ResponsiveDialogStateProps,
	type ResponsiveDialogVariant
} from './responsive-dialog.svelte.js';

export {
	Root,
	Trigger,
	Close,
	Portal,
	Overlay,
	Content,
	Header,
	Footer,
	Title,
	Description,
	//
	Root as ResponsiveDialog,
	Trigger as ResponsiveDialogTrigger,
	Close as ResponsiveDialogClose,
	Portal as ResponsiveDialogPortal,
	Overlay as ResponsiveDialogOverlay,
	Content as ResponsiveDialogContent,
	Header as ResponsiveDialogHeader,
	Footer as ResponsiveDialogFooter,
	Title as ResponsiveDialogTitle,
	Description as ResponsiveDialogDescription
};

import { getContext, hasContext, setContext, untrack } from 'svelte';

import { IsMobile } from '$lib/hooks/is-mobile.svelte.js';

/** Which primitive the composition is currently rendering. */
export type ResponsiveDialogVariant = 'dialog' | 'drawer';

export type ResponsiveDialogStateProps = {
	/** Reads the root's resolved open state (controlled prop or uncontrolled seed). */
	readonly getOpen: () => boolean;
	/** Writes the root's open state and invokes `onOpenChange`. */
	readonly setOpen: (open: boolean) => void;
	/** Reads the root's `breakpoint` prop. */
	readonly getBreakpoint: () => number;
};

/**
 * One instance per `<ResponsiveDialog.Root>`, published on context; every part reads it.
 *
 * Replaces upstream's `useSyncExternalStore` pub/sub `Store` — `$state`/`$derived` are synchronous
 * and fine-grained, so the whole abstraction collapses to two reactive fields.
 */
export class ResponsiveDialogState {
	// $derived below is lazy at runtime (evaluated only when a member is read), but svelte-check's
	// static analysis cannot see that and flags the fields as used before their constructor
	// assignment.
	#props!: ResponsiveDialogStateProps;
	#isMobile!: IsMobile;
	/** Non-reactive previous value, used to detect a mode transition inside `untrack`. */
	#lastVariant: ResponsiveDialogVariant | undefined;

	readonly open: boolean = $derived(this.#props.getOpen());
	readonly variant: ResponsiveDialogVariant = $derived(
		this.#isMobile.current ? 'drawer' : 'dialog'
	);

	/** Set when `variant` changes while `open` is `true`; consumed by the newly mounted `Content`. */
	pendingFocusRestore: boolean = $state(false);

	constructor(props: ResponsiveDialogStateProps) {
		this.#props = props;
		this.#isMobile = new IsMobile(props.getBreakpoint);

		// `$effect.pre` — the flag has to be raised *before* the `{#if}` swaps the branch, so the
		// `Content` mounting in the new branch can consume it in its own mount effect.
		$effect.pre(() => {
			const variant = this.variant;

			untrack(() => {
				if (this.#lastVariant !== undefined && this.#lastVariant !== variant && this.open) {
					this.pendingFocusRestore = true;
				}
				this.#lastVariant = variant;
			});
		});
	}

	/**
	 * Writes the open state through the root.
	 *
	 * No-op when `from` is not the active variant — the callback then comes from a branch being torn
	 * down by a mode swap and must not close a dialog the user never closed — or when `next` is
	 * already the current value, mirroring upstream's `Object.is` short-circuit.
	 */
	setOpen(next: boolean, from: ResponsiveDialogVariant): void {
		if (from !== this.variant) return;
		if (Object.is(this.open, next)) return;
		this.#props.setOpen(next);
	}

	/** Returns and clears {@link pendingFocusRestore}. */
	consumeFocusRestore(): boolean {
		if (!this.pendingFocusRestore) return false;
		this.pendingFocusRestore = false;
		return true;
	}
}

const RESPONSIVE_DIALOG_CONTEXT_KEY = Symbol('responsive-dialog');

export function setResponsiveDialogContext(state: ResponsiveDialogState): ResponsiveDialogState {
	return setContext(RESPONSIVE_DIALOG_CONTEXT_KEY, state);
}

export function hasResponsiveDialogContext(): boolean {
	return hasContext(RESPONSIVE_DIALOG_CONTEXT_KEY);
}

export function getResponsiveDialogContext(part?: string): ResponsiveDialogState {
	if (!hasResponsiveDialogContext()) {
		throw new Error(
			`\`<ResponsiveDialog.${part ?? 'Part'}>\` must be used within \`<ResponsiveDialog.Root>\`.`
		);
	}
	return getContext<ResponsiveDialogState>(RESPONSIVE_DIALOG_CONTEXT_KEY);
}
